import {ASSETS} from './assets.js';
import {SoundEngine} from './sound.js?v=music3';
export const W=1000,H=640,T=40,GRAVITY=1680;
const SOLID=new Set(['G','D','S','B','Q','U','X']);
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
const body=(x,y,w,h,vx=0,vy=0)=>({x,y,w,h,vx,vy});
const newPlayer=(hp=5)=>({...body(80,514,28,46),hp,facing:1,grounded:false,jumps:2,invulnerable:0,star:0,cooldown:0,jump_buffer:0,coyote:0});
const tileKey=(x,y)=>`${x},${y}`;
export function makeLevel(i){const l=JSON.parse(JSON.stringify(ASSETS.levels[i]));l.tiles=new Map(l.tiles.map(([x,y,k])=>[tileKey(x,y),k]));l.built=new Set();return l;}
export class Game{
 constructor(){this.onSound=()=>{};this.stepTimer=0;this.bossWarned=false;this.state='menu';this.time=0;this.score=0;this.coins=0;this.materials=20;this.level_index=0;this.level=makeLevel(0);this.player=newPlayer();this.particles=[];this.shots=[];this.camera=0;this.checkpoint=false;this.build_mode=false;this.message='';this.message_time=0;this.entry_score=0;this.entry_coins=0;this.entry_materials=20;this.entry_hp=5;}
 sound(name){this.onSound(name);}
 start(i=0){this.time=0;this.score=this.coins=0;this.materials=20;this.loadLevel(i,5);}
 loadLevel(i,hp){this.stepTimer=0;this.bossWarned=false;this.level_index=i;this.level=makeLevel(i);this.player=newPlayer(hp);this.particles=[];this.shots=[];this.camera=0;this.checkpoint=false;this.build_mode=false;this.state='play';this.entry_score=this.score;this.entry_coins=this.coins;this.entry_materials=this.materials;this.entry_hp=hp;this.notify('陈燕丽，出发！到达右侧传送门即可过关。',4);this.sound('start');}
 restart(){this.score=this.entry_score;this.coins=this.entry_coins;this.materials=this.entry_materials;this.loadLevel(this.level_index,this.entry_hp);}
 advance(){if(this.level_index===2)this.state='win';else this.loadLevel(this.level_index+1,Math.min(5,this.player.hp+1));}
 notify(t,s=2.5){this.message=t;this.message_time=s;}
 burst(x,y,color,n=12){for(let i=0;i<n;i++)this.particles.push({x,y,vx:Math.random()*320-160,vy:Math.random()*260-230,color,life:Math.random()*.45+.3,size:4});}
 solidAt(x,y){return SOLID.has(this.level.tiles.get(tileKey(Math.floor(x/T),Math.floor(y/T))));}
 *nearby(b){for(let y=Math.floor(b.y/T)-1;y<=Math.floor((b.y+b.h)/T)+1;y++)for(let x=Math.floor(b.x/T)-1;x<=Math.floor((b.x+b.w)/T)+1;x++){const k=this.level.tiles.get(tileKey(x,y));if(SOLID.has(k))yield[x,y,k,body(x*T,y*T,T,T)];}}
 move(b,dt,player=false,enemy=false){let grounded=false;b.x+=b.vx*dt;for(const[x,y,k,t]of this.nearby(b))if(overlap(b,t)){if(b.vx>0)b.x=t.x-b.w;else if(b.vx<0)b.x=t.x+t.w;if(enemy)b.vx=-b.vx;else b.vx=0;}b.x=clamp(b.x,0,this.level.width*T-b.w);b.y+=b.vy*dt;for(const[x,y,k,t]of this.nearby(b))if(overlap(b,t)){if(b.vy>0){b.y=t.y-b.h;grounded=true;}else if(b.vy<0){b.y=t.y+t.h;if(player&&k==='Q')this.hitBlock(x,y);}b.vy=0;}return grounded;}
 hitBlock(x,y){this.level.tiles.set(tileKey(x,y),'U');this.sound('block');this.burst(x*T+20,y*T,'#ffe784');if((x+this.level_index)%4===0){this.player.hp=Math.min(5,this.player.hp+1);this.notify('隐藏奖励：恢复一颗爱心！');}else if((x+this.level_index)%7===0){this.player.star=8;this.notify('星光护盾：8 秒内碰到怪物也不会受伤！');}else{this.coins+=3;this.score+=150;this.materials+=2;this.notify('宝箱奖励：金币 +3，方块 +2');}}
 damage(falling=false,source=null){const p=this.player;if(!falling&&(p.invulnerable>0||p.star>0))return;p.hp--;this.burst(p.x+p.w/2,p.y+p.h/2,'#ff8fa8',16);if(p.hp<=0){this.state='gameover';this.sound('gameover');return;}this.sound(falling?'fall':'hurt');p.invulnerable=1.7;if(falling){p.x=this.checkpoint?this.level.checkpoint_x:80;p.y=514;p.vx=p.vy=0;p.jumps=2;p.jump_buffer=0;this.camera=clamp(p.x-300,0,this.level.width*T-W);this.notify('别怕，站起来继续冒险！');}else{p.vx=source!==null&&source>p.x?-240:240;p.vy=-330;this.notify('受伤了！短暂无敌期间可以躲开怪物。',1.6);}}
 hitEnemy(e,power=1){e.hp-=power;e.flash=.18;this.sound(e.hp<=0?(e.kind==='guardian'?'bossDefeat':'defeat'):'hit');if(e.hp<=0){e.dead=true;this.score+=e.kind==='guardian'?500:120;this.coins+=e.kind==='guardian'?5:1;this.materials++;this.burst(e.x+e.w/2,e.y+e.h/2,e.kind==='bat'?'#c5b7ff':'#8fffc3',20);if(e.kind==='guardian')this.notify('城堡守卫已击败，传送门开启！',3);}}
 shoot(){const p=this.player;if(this.state!=='play'||p.cooldown>0)return;this.shots.push(body(p.x+p.w/2+p.facing*24,p.y+20,12,12,p.facing*570));p.cooldown=.32;this.sound('magic');this.burst(p.x+p.w/2+p.facing*22,p.y+26,'#a3f6ff',4);}
 build(tx,ty,remove=false){if(this.state!=='play'||!this.build_mode)return false;const p=this.player,key=tileKey(tx,ty),l=this.level;if(Math.hypot(tx*T+20-(p.x+p.w/2),ty*T+20-(p.y+p.h/2))>205){this.notify('只能改造身边 5 格以内的区域。',1.2);return false;}if(remove){if(l.built.has(key)){l.tiles.delete(key);l.built.delete(key);this.materials++;this.sound('recover');return true;}this.notify('只能回收自己放置的方块。',1.2);return false;}if(this.materials<=0){this.notify('方块用完了，打怪或顶宝箱可以补充。');return false;}const b=body(tx*T,ty*T,T,T);if(tx<0||tx>=l.width||ty<3||ty>14||l.tiles.has(key)||overlap(p,b)||Math.abs(tx*T-l.portal_x)<100||Math.abs(tx*T-l.checkpoint_x)<65||l.enemies.some(e=>!e.dead&&overlap(e,b))||l.hazards.some(h=>overlap(h,b)))return false;l.tiles.set(key,'X');l.built.add(key);this.materials--;this.sound('place');this.burst(tx*T+20,ty*T+20,'#9eeed9',6);return true;}
 update(dt,keys){if(this.state!=='play')return;this.time+=dt;const p=this.player,l=this.level,wasGrounded=p.grounded;for(const k of['invulnerable','star','cooldown','jump_buffer'])p[k]=Math.max(0,p[k]-dt);p.coyote=p.grounded?.1:Math.max(0,p.coyote-dt);this.message_time=Math.max(0,this.message_time-dt);
 const axis=Number(keys.has('right')||keys.has('d'))-Number(keys.has('left')||keys.has('a'));const speed=keys.has('shift')?350:245,target=axis*speed;let acceleration=p.grounded?2000:1450;if(p.invulnerable>1.4)acceleration=420;p.vx+=clamp(target-p.vx,-acceleration*dt,acceleration*dt);if(axis)p.facing=axis;
 if(p.jump_buffer>0&&(p.jumps>0||p.coyote>0)){if(p.coyote>0)p.jumps=2;this.sound(p.jumps===2?'jump':'doubleJump');p.vy=-655;p.jumps--;p.jump_buffer=p.coyote=0;p.grounded=false;this.burst(p.x+p.w/2,p.y+p.h,'#f5cfef',8);}if(keys.has('j'))this.shoot();p.vy=Math.min(900,p.vy+GRAVITY*dt);const prevBottom=p.y+p.h;const landingSpeed=p.vy;p.grounded=this.move(p,dt,true);if(p.grounded){p.jumps=2;if(!wasGrounded&&landingSpeed>250)this.sound('land');if(Math.abs(p.vx)>90){this.stepTimer-=dt;if(this.stepTimer<=0){this.sound('step');this.stepTimer=keys.has('shift')?.19:.29;}}else this.stepTimer=.08;}else this.stepTimer=.08;if(p.y>H+80){this.damage(true);return;}
 for(const item of l.pickups)if(!item.collected&&overlap(p,item)){item.collected=true;let color;if(item.kind==='coin'){this.sound('coin');this.coins++;this.score+=50;color='#ffe58c';}else if(item.kind==='heart'){this.sound('heal');p.hp=Math.min(5,p.hp+1);this.notify('拾取爱心，恢复生命！');color='#ff8faa';}else{this.sound('power');p.star=8;this.notify('获得星光护盾！');color='#fff3b0';}this.burst(item.x+item.w/2,item.y+item.h/2,color,8);}
 for(const e of l.enemies){if(e.dead)continue;if(e.kind==='guardian'&&!this.bossWarned&&Math.abs(e.x-p.x)<450){this.bossWarned=true;this.sound('boss');}e.flash=Math.max(0,e.flash-dt);if(e.kind==='bat'){e.x+=e.vx*dt;if(e.x<e.left||e.x>e.right){e.vx=-e.vx;e.x=clamp(e.x,e.left,e.right);}e.y=e.base_y+Math.sin(this.time*2.5+e.phase)*35;}else{e.vy=Math.min(900,e.vy+GRAVITY*dt);const landed=this.move(e,dt,false,true);if(landed){const ahead=e.vx>0?e.x+e.w+5:e.x-5;if(!this.solidAt(ahead,e.y+e.h+4))e.vx=-e.vx;}if(e.y>H+120){e.dead=true;continue;}}if(overlap(p,e)){if(p.star>0)this.hitEnemy(e,10);else if(p.vy>=0&&prevBottom<=e.y+13){this.hitEnemy(e);this.sound('stomp');p.y=e.y-p.h;p.vy=-460;p.jumps=Math.max(1,p.jumps);}else this.damage(false,e.x);}if(this.state!=='play')return;}
 for(const h of l.hazards)if(overlap(p,h))this.damage(false,h.x);if(this.state!=='play')return;
 this.shots=this.shots.filter(s=>{s.x+=s.vx*dt;let hit=[...this.nearby(s)].some(t=>overlap(s,t[3]));if(!hit)for(const e of l.enemies)if(!e.dead&&overlap(s,e)){this.hitEnemy(e);hit=true;break;}return !hit&&Math.abs(s.x-p.x)<850;});
 if(!this.checkpoint&&Math.abs(p.x-l.checkpoint_x)<48&&p.y>420){this.checkpoint=true;this.sound('checkpoint');p.hp=Math.min(5,p.hp+1);this.notify('存档点已激活，摔落后从这里继续。',3);this.burst(l.checkpoint_x,490,'#bff7dc',25);}
 if(overlap(p,body(l.portal_x,440,72,120))){if(l.enemies.some(e=>e.kind==='guardian'&&!e.dead))this.notify('先击败城堡守卫，再进入传送门。',1);else{this.score+=600+p.hp*100;this.state=this.level_index<2?'stageclear':'win';this.sound(this.state==='win'?'win':'clear');this.burst(l.portal_x+30,490,'#d9b5ff',40);}}
 const cam=clamp(p.x-W*.36,0,l.width*T-W);this.camera+=(cam-this.camera)*Math.min(1,dt*7);this.particles=this.particles.filter(p=>{p.life-=dt;if(p.life<=0)return false;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=550*dt;return true;}).slice(-180);
 }
}

export class Renderer{
 constructor(canvas,game){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.ctx.imageSmoothingEnabled=false;this.g=game;this.cache=new Map();}
 rect(x,y,w,h,c){this.ctx.fillStyle=c;this.ctx.fillRect(Math.round(x),Math.round(y),w,h);}
 text(x,y,t,s=16,c='#fff0de',align='center',bold=false){const ctx=this.ctx;ctx.font=`${bold?'600':'400'} ${s}px -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif`;ctx.fillStyle=c;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(t,x,y);}
 sprite(name,scale=2,flip=false,frame=0){const key=`${name}:${scale}:${flip}:${frame}`;if(this.cache.has(key))return this.cache.get(key);const rows=ASSETS.pixels[name],width=Math.max(...rows.map(s=>s.length));let pixels=rows.map(r=>r.padEnd(width,'.').split(''));
 if(name==='hero'&&frame){for(const y of[19,20,21,22])pixels[y]=Array(width).fill('.');for(const y of[19,20])for(const x of[4,5,10,11])pixels[y][x]='s';for(const x of[3,4,5,10,11,12])pixels[21][x]=pixels[22][x]='k';}if(name==='slime'&&frame)pixels=[Array(width).fill('.'),Array(width).fill('.'),...pixels.slice(0,-2)];if(flip)pixels=pixels.map(r=>r.reverse());const c=document.createElement('canvas');c.width=width*scale;c.height=pixels.length*scale;const x=c.getContext('2d');for(let y=0;y<pixels.length;y++)for(let j=0;j<width;j++){const color=ASSETS.palettes[name][pixels[y][j]];if(color){x.fillStyle=color;x.fillRect(j*scale,y*scale,scale,scale);}}this.cache.set(key,c);return c;}
 image(x,y,name,scale=2,flip=false,frame=0){this.ctx.drawImage(this.sprite(name,scale,flip,frame),Math.round(x),Math.round(y));}
 tile(kind,theme){const key=`tile:${kind}:${theme}`;if(this.cache.has(key))return this.cache.get(key);const c=document.createElement('canvas');c.width=c.height=40;const x=c.getContext('2d');let base,spot,top;if(kind==='G')[base,spot,top]=['#a17c69','#866452','#84b78b'];else if(kind==='D')[base,spot,top]=['#9a7868','#795c52','#aa8974'];else if(kind==='S')[base,spot,top]=['#797890','#605f7b','#b2abc1'];else if(kind==='B')[base,spot,top]=theme===0?['#b29488','#826c77','#dbc1a1']:['#8b81a5','#625d80','#b5a5c8'];else if(kind==='Q')[base,spot,top]=['#e6b86c','#bf854e','#ffe5a1'];else if(kind==='U')[base,spot,top]=['#a28b7f','#816d71','#c5b299'];else[base,spot,top]=['#69aaae','#3e7f8d','#acf0d5'];const r=(a,b,w,h,color)=>{x.fillStyle=color;x.fillRect(a*2,b*2,w*2,h*2);};r(0,0,20,20,base);r(0,0,20,2,top);r(0,18,20,2,spot);r(18,2,2,18,spot);for(let i=0;i<13;i++)r(2+(i*7+kind.charCodeAt(0))%15,4+(i*3)%13,2,2,spot);if(kind==='G'){r(0,0,20,4,top);for(let i=0;i<20;i+=4)r(i,3,2,3,'#638e73');}if(kind==='B'){for(const y of[7,14])r(0,y,20,1,spot);for(const[a,b]of[[10,2],[5,8],[15,8],[10,15]])r(a,b,1,Math.min(6,20-b),spot);}if(kind==='Q'){['.xxx.','x...x','....x','...x.','..x..','.....','..x..'].forEach((row,y)=>[...row].forEach((p,j)=>{if(p==='x')r(5+j*2,3+y*2,2,2,'#fff4cf');}));}if(kind==='X'){r(4,4,12,2,top);r(4,6,2,10,top);}this.cache.set(key,c);return c;}
 background(theme,cam){const colors=[['#e8d2cc','#eddbce','#f1e3d0','#f7ebd7','#c7b9be','#9eabb2','#8baaa2'],['#a9a5c8','#b9afd0','#cebad3','#ddc5d5','#9d92b5','#7d7e9e','#686f8c'],['#292d51','#33385d','#424465','#55506f','#4c486e','#57516e','#67607a']][theme];for(let n=0;n<4;n++)this.rect(0,n*130,W,130,colors[n]);this.rect(0,520,W,120,colors[3]);const sun=theme<2?'#fff1be':'#ede5ff';this.rect(804,100,60,60,sun);this.rect(796,108,76,44,sun);if(theme===2)for(let n=0;n<36;n++)this.rect((n*137+43)%W,92+(n*79)%260,2+n%2*2,2+n%2*2,'#bcb5d6');
 for(let n=0;n<7;n++){const x=((n*220-cam*.12)%(W+260)+(W+260))%(W+260)-180,y=136+n%3*42,c=theme<2?'#fff3e2':'#66617f';this.rect(x,y+14,112,20,c);this.rect(x+18,y,68,40,c);this.rect(x+88,y+20,38,14,c);}
 for(let l=0;l<3;l++){const baseline=460+l*40,parallax=[.16,.28,.42][l];for(let n=-2;n<12;n++){const x=n*150-(cam*parallax)%150,h=90+((n+l*5+8)%4)*25;this.rect(x,baseline-h,150,h+180,colors[4+l]);this.rect(x+22,baseline-h-30,106,30,colors[4+l]);this.rect(x+48,baseline-h-50,54,20,colors[4+l]);}}
 if(theme<2)for(let n=0;n<8;n++){const x=n*180-(cam*.55)%180,trunk=theme===0?'#8c7985':'#655d7f',leaf=theme===0?'#7b9b91':'#8b82a5';this.rect(x+35,410,14,150,trunk);this.rect(x+5,366,72,66,leaf);this.rect(x+17,342,48,26,leaf);this.rect(x-7,388,96,30,leaf);}else for(let n=0;n<4;n++){const x=n*310-(cam*.4)%310;this.rect(x,320,120,240,'#5b5575');this.rect(x-12,290,36,270,'#655e7d');this.rect(x+96,290,36,270,'#655e7d');for(const bx of[x-12,x,x+12,x+96,x+108,x+120])this.rect(bx,280,8,15,'#655e7d');this.rect(x+42,375,32,90,'#8d8098');}this.text(502,110,'陈燕丽的异世界生活',31,'#79758b','center',true);this.text(500,108,'陈燕丽的异世界生活',31,theme<2?'#fff0de':'#d9c9ec','center',true);
 }
 render(){const g=this.g,l=g.level,p=g.player,cam=g.camera;this.ctx.clearRect(0,0,W,H);this.background(g.level_index,cam);
 for(const[a,b]of l.gaps){const x=a*T-cam;if(x>W||x+(b-a)*T<0)continue;this.rect(x,596,(b-a)*T,44,g.level_index<2?'#8d5768':'#6f5c98');for(let n=a;n<b;n++)this.rect(n*T-cam,594+Math.sin(g.time*3+n)*3,40,8,g.level_index<2?'#eaa17f':'#b796dc');}
 for(const[key,k]of l.tiles){const[tx,ty]=key.split(',').map(Number),x=tx*T-cam;if(x>-T&&x<W)this.ctx.drawImage(this.tile(k,g.level_index),Math.round(x),ty*T);}
 for(let tx=Math.max(0,Math.floor(cam/T));tx<Math.min(l.width,Math.floor((cam+W)/T)+1);tx++)if(l.tiles.get(tileKey(tx,14))==='G'&&tx%3===0){const x=tx*T-cam+8;this.rect(x,552,3,8,'#638e73');this.rect(x-3,548,8,5,tx%2?'#f3bdc4':'#f1e3a0');}
 for(const item of l.pickups)if(!item.collected&&item.x-cam>-40&&item.x-cam<W+40)this.image(item.x-cam,item.y+Math.sin(g.time*3+item.phase)*4,item.kind);
 const cx=l.checkpoint_x-cam;if(cx>-70&&cx<W+70){this.rect(cx,470,5,90,'#d9ccb5');this.rect(cx+5,473,39,28,g.checkpoint?'#8ed8bb':'#e1b597');this.text(cx+22,453,'存档点',12);}
 const px=l.portal_x-cam;if(px>-100&&px<W+100){this.rect(px-6,426,84,134,'#8d75b4');this.rect(px+2,434,68,126,'#ead8f2');this.rect(px+10,442,52,118,'#53466c');for(let n=0;n<10;n++)this.rect(px+16+n*17%40,451+(n*21+g.time*32)%98,4,4,'#c6b5fa');this.text(px+36,403,'传送门',14,'#fff1db','center',true);}
 for(const h of l.hazards){const hx=h.x-cam;if(hx>-80&&hx<W)for(let n=0;n<4;n++){this.ctx.beginPath();this.ctx.moveTo(hx+n*18,560);this.ctx.lineTo(hx+n*18+9,542);this.ctx.lineTo(hx+n*18+18,560);this.ctx.closePath();this.ctx.fillStyle='#d9d4e1';this.ctx.fill();}}
 for(const e of l.enemies){if(e.dead||e.x-cam<-80||e.x-cam>W+80||e.flash>0&&Math.floor(g.time*40)%2===0)continue;const x=e.x-cam;if(e.kind==='guardian'){this.image(x,e.y-4,'crab',4,e.vx<0);this.rect(x,e.y-14,64,5,'#463c60');this.rect(x,e.y-14,64*Math.max(0,e.hp)/6,5,'#f2b18f');this.text(x+32,e.y-30,'城堡守卫',12);}else this.image(x,e.y-2,e.kind,2,e.vx<0,e.kind==='slime'?Math.floor(g.time*4)%2:0);}
 const sx=p.x-cam;if(p.grounded)this.rect(sx-4,p.y+p.h-3,36,5,'#79687b');if(p.star>0){this.ctx.strokeStyle='#ffe7a0';this.ctx.lineWidth=3;this.ctx.beginPath();this.ctx.ellipse(sx+15,p.y+22,27,34,0,0,Math.PI*2);this.ctx.stroke();for(let n=0;n<5;n++){const a=g.time*2+n*Math.PI*2/5;this.rect(sx+14+Math.cos(a)*35,p.y+23+Math.sin(a)*35,4,4,'#fff2bb');}}
 if(p.invulnerable<=0||Math.floor(g.time*12)%2===0){const f=Math.abs(p.vx)>20&&p.grounded?Math.floor(g.time*9)%2:0;this.image(sx-2,p.y-2,'hero',2,p.facing<0,f);this.text(sx+15,p.y-15,'陈燕丽',12,'#fff0de','center',true);}
 for(const s of g.shots){this.rect(s.x-cam-5,s.y-3,22,18,'#77b9c5');this.rect(s.x-cam,s.y,12,12,'#c5fff0');this.rect(s.x-cam+3,s.y+3,6,6,'#ffffff');}for(const p of g.particles)this.rect(p.x-cam,p.y,p.size,p.size,p.color);
 if(g.build_mode){this.ctx.strokeStyle='#b3b7b155';this.ctx.lineWidth=1;this.ctx.beginPath();for(let x=(((-Math.floor(cam))%T)+T)%T;x<W;x+=T){this.ctx.moveTo(x,160);this.ctx.lineTo(x,600);}for(let y=160;y<=600;y+=T){this.ctx.moveTo(0,y);this.ctx.lineTo(W,y);}this.ctx.stroke();}
 this.hud();
 }
 hud(){const g=this.g,p=g.player;this.rect(0,0,W,72,'#333047');this.rect(0,70,W,2,'#71657e');this.text(22,18,'陈燕丽',15,'#fff0de','left',true);for(let n=0;n<5;n++)if(n<p.hp)this.image(19+n*27,34,'heart');else this.rect(24+n*27,39,14,12,'#665469');this.image(178,23,'coin');this.text(204,35,String(g.coins).padStart(3,'0'),18,'#fff0de','left',true);this.text(295,23,'冒险分数',11,'#bdb0c7','left');this.text(295,45,String(g.score).padStart(5,'0'),17,'#fff0de','left',true);this.text(500,27,g.level.name,17,'#fff0de','center',true);this.rect(422,49,156,5,'#63536e');this.rect(422,49,156*clamp(p.x/g.level.portal_x,0,1),5,'#e8b3c1');this.text(665,24,`方块 ${g.materials}`,13);this.text(665,47,g.build_mode?'建造中':'探索异世界',11,g.build_mode?'#a7e2cd':'#bdb0c7');this.text(821,24,'二段跳 · 魔法攻击',13);this.text(821,48,p.star>0?`护盾 ${Math.ceil(p.star)}s`:'收集金币，到达传送门',11,p.star>0?'#ffe4a5':'#bdb0c7');this.rect(0,614,W,26,'#333047');this.text(500,626,g.build_mode?'点击身边空位放方块，切换回收可取回自建方块':'陈燕丽的异世界生活 · 冒险从每一步开始',12,'#ded0dc');}
}

export function canvasPoint(canvas,clientX,clientY){const r=canvas.getBoundingClientRect(),s=Math.min(r.width/W,r.height/H),ox=(r.width-W*s)/2,oy=(r.height-H*s)/2;return{x:(clientX-r.left-ox)/s,y:(clientY-r.top-oy)/s};}

export function boot(){const $=id=>document.getElementById(id),canvas=$('game'),game=new Game(),audio=new SoundEngine(),renderer=new Renderer(canvas,game),keys=new Set(),pointers=new Map();let record={best:0,unlocked:0},removeMode=false,oldState='',last=performance.now(),accum=0;
 try{const r=JSON.parse(localStorage.getItem('chen-yanli-web')||'{}');record.best=Math.max(0,Number(r.best)||0);record.unlocked=clamp(Number(r.unlocked)||0,0,2);}catch{}
 audio.prewarm();game.onSound=name=>{audio.setScene(game.state,game.level_index);audio.play(name);};
 const soundButton=$('sound'),soundStatus=$('soundStatus');let testing=false;const updateSoundButton=()=>{soundButton.textContent=!audio.enabled?'声音关':audio.ready?'声音开':'点按开声';soundButton.setAttribute('aria-pressed',String(audio.enabled));$('music').textContent=audio.musicEnabled?'音乐开':'音乐关';$('music').setAttribute('aria-pressed',String(audio.musicEnabled));soundButton.title=audio.enabled&&audio.ready?'关闭音效':'开启音效';if(!audio.enabled)soundStatus.textContent='音效已关闭，点“试音”可重新开启。';else if(audio.lastError)soundStatus.textContent=audio.lastError;else if(!testing)soundStatus.textContent=audio.ready?'音乐增强版 · 音效已启用，三关配乐会随冒险切换。':'音乐增强版 · 点“试音”或“开始冒险”，开启配乐与音效。';};audio.onState=updateSoundButton;updateSoundButton();soundButton.onclick=()=>{audio.setEnabled(!(audio.enabled&&audio.ready));if(audio.enabled)audio.unlock().then(ok=>{if(ok)audio.play('click');});};
 $('soundTest').onclick=()=>{testing=true;soundStatus.textContent='正在播放三声测试音…';audio.test().then(ok=>{testing=false;updateSoundButton();if(ok)soundStatus.textContent='已发出三声试音。仍听不到时，请调高媒体音量，并在 Safari / Chrome 打开。';});};
 $('music').onclick=()=>{audio.setMusicEnabled(!audio.musicEnabled);if(audio.musicEnabled){audio.setEnabled(true);audio.unlock();}};$('fxVolume').value=audio.fxVolume;$('musicVolume').value=audio.musicVolume;$('compatAudio').checked=audio.compat;$('fxVolume').oninput=e=>audio.setVolume('fx',e.target.value);$('musicVolume').oninput=e=>audio.setVolume('music',e.target.value);$('compatAudio').onchange=e=>audio.setCompat(e.target.checked);
 const activateAudio=e=>{if(['soundTest','sound','music','compatAudio'].includes(e.target?.id))return;void audio.unlock();};for(const event of ['pointerdown','pointerup','touchend','click'])document.addEventListener(event,activateAudio,{capture:true,passive:true});document.addEventListener('keydown',activateAudio,{capture:true});
 const save=()=>{record.best=Math.max(record.best,game.score);if(['stageclear','win'].includes(game.state))record.unlocked=Math.max(record.unlocked,Math.min(2,game.level_index+1));try{localStorage.setItem('chen-yanli-web',JSON.stringify(record));}catch{}};
 const releaseAll=()=>{keys.clear();pointers.clear();document.querySelectorAll('.touch').forEach(b=>b.classList.remove('pressed'));};
 const act=(name,i=0)=>{audio.unlock();if(!['start','next','restart'].includes(name))audio.play('click');releaseAll();removeMode=false;if(name==='start')game.start(i);if(name==='next')game.advance();if(name==='restart')game.restart();if(name==='resume')game.state='play';if(name==='menu'){save();game.state='menu';}oldState='';};
 const press=key=>{if(!keys.has(key)&&key==='jump'&&game.state==='play')game.player.jump_buffer=.15;keys.add(key);};
 const release=key=>{keys.delete(key);if(key==='jump'&&game.player.vy<-280)game.player.vy*=.6;};
 for(const b of document.querySelectorAll('.touch')){b.addEventListener('pointerdown',e=>{e.preventDefault();if(game.state!=='play')return;b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,b.dataset.key);b.classList.add('pressed');press(b.dataset.key);});const up=e=>{e.preventDefault();const k=pointers.get(e.pointerId);pointers.delete(e.pointerId);if(k&&!Array.from(pointers.values()).includes(k))release(k);b.classList.remove('pressed');};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up);}
 const pause=()=>{audio.play('click');if(game.state==='play'){game.state='paused';releaseAll();}else if(game.state==='paused')act('resume');};
 const build=()=>{if(game.state!=='play')return;audio.play('click');game.build_mode=!game.build_mode;removeMode=false;game.notify(game.build_mode?'建造已开启：点空位放方块，切换“回收”可取回。':'已返回冒险模式。');};
 $('pause').onclick=pause;$('build').onclick=build;$('recover').onclick=()=>{removeMode=!removeMode;game.notify(removeMode?'回收模式：点自己放置的方块。':'放置模式：点身边空位搭方块。');};$('home').onclick=()=>act('menu');
 $('fullscreen').onclick=()=>{if(document.body.classList.contains('immersive')){document.body.classList.remove('immersive');if(document.fullscreenElement)document.exitFullscreen?.();}else{document.body.classList.add('immersive');$('playArea').parentElement.requestFullscreen?.().catch(()=>{});}};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('immersive');});
 canvas.addEventListener('pointerdown',e=>{if(!game.build_mode||game.state!=='play')return;e.preventDefault();const p=canvasPoint(canvas,e.clientX,e.clientY);if(p.x<0||p.x>W||p.y<115||p.y>H)return;game.build(Math.floor((p.x+game.camera)/T),Math.floor(p.y/T),removeMode||e.button===2);});canvas.addEventListener('contextmenu',e=>e.preventDefault());
 const keyMap={arrowleft:'left',arrowright:'right',a:'left',d:'right',' ':'jump',w:'jump',arrowup:'jump',shift:'shift',j:'j'};
 window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(keyMap[k]||['p','b','r','escape','enter'].includes(k))e.preventDefault();if(e.repeat)return;if(keyMap[k])press(keyMap[k]);else if(k==='p')pause();else if(k==='b')build();else if(k==='escape')act('menu');else if(k==='r'&&game.state!=='menu')act(game.state==='win'?'start':'restart');else if(k==='enter'){if(game.state==='menu')act('start');else if(game.state==='stageclear')act('next');}});window.addEventListener('keyup',e=>{const k=keyMap[e.key.toLowerCase()];if(k)release(k);});
 const blur=()=>{audio.setScene('paused',game.level_index);audio.silence();releaseAll();if(game.state==='play')game.state='paused';};window.addEventListener('blur',blur);document.addEventListener('visibilitychange',()=>{if(document.hidden)blur();});
 function overlay(){const state=game.state;if(state===oldState)return;oldState=state;$('overlay').hidden=state==='play';if(state==='play')return;if(['stageclear','win','gameover'].includes(state))save();let title,description,buttons;
 if(state==='menu'){title='陈燕丽的异世界生活';description='捡金币、踩怪兽、搭方块，走进你的异世界。';buttons=[['开始冒险','start',0]];}else if(state==='paused'){title='旅途暂停';description='休息一下，异世界会等你回来。';buttons=[['继续冒险','resume',0],['重开本关','restart',0]];}else if(state==='gameover'){title='下一次，会走得更远';description='陈燕丽，整理好行囊，再出发吧。';buttons=[['重试本关','restart',0],['回到首页','menu',0]];}else if(state==='stageclear'){title='世界探索完成';description='下一片风景，正在等待陈燕丽。';buttons=[['进入下一关','next',0],['回到首页','menu',0]];}else{title='陈燕丽的冒险圆满完成';description='金币、勇气和星光，都是这段旅途的纪念。';buttons=[['再来一次','start',0],['回到首页','menu',0]];}
 $('dialog').innerHTML=`<div class="kicker">${state==='menu'?'PIXEL ADVENTURE · 3 WORLDS':'THE JOURNEY OF CHEN YANLI'}</div><h2>${title}</h2><p>${description}</p>${state!=='menu'&&state!=='paused'?`<div class="result">分数 ${game.score} &nbsp; 金币 ${game.coins}</div>`:''}<div id="dialogButtons"></div>${state==='menu'?`<div class="records">最高分 ${record.best} · 已解锁 ${record.unlocked+1}/3</div><div class="level-picker" id="levelPicker"></div>`:''}`;
 buttons.forEach(([label,action,i],n)=>{const b=document.createElement('button');b.type='button';b.className=n?'secondary':'primary';b.textContent=label;b.onclick=()=>act(action,i);$('dialogButtons').append(b);});if(state==='menu')['风铃草原','暮色矿谷','星光城堡'].forEach((label,i)=>{const b=document.createElement('button');b.type='button';b.textContent=label+(i>record.unlocked?' · 锁定':'');b.disabled=i>record.unlocked;b.onclick=()=>act('start',i);$('levelPicker').append(b);});
 }
 const setText=(el,t)=>{if(el.textContent!==t)el.textContent=t;};function frame(now){audio.setScene(document.hidden?'paused':game.state,game.level_index);accum+=Math.min(.065,(now-last)/1000);last=now;while(accum>=1/120){game.update(1/120,keys);accum-=1/120;}renderer.render();overlay();setText($('hpLabel'),'♥ '.repeat(Math.max(0,game.player.hp))+'♡ '.repeat(5-Math.max(0,game.player.hp)));setText($('coinLabel'),`金币 ${game.coins}`);setText($('toast'),game.state==='play'&&game.message_time>0?game.message:'');$('build').setAttribute('aria-pressed',String(game.build_mode&&game.state==='play'));$('recover').hidden=!game.build_mode||game.state!=='play';$('recover').setAttribute('aria-pressed',String(removeMode));setText($('pause'),game.state==='paused'?'继续':'暂停');requestAnimationFrame(frame);}requestAnimationFrame(frame);return{game,renderer,audio,keys,act,press,release};
}
if(typeof document!=='undefined')boot();
